class ScriptFailed(Exception):  # noqa: N818  # reads as what happened
    """A saved script raised, returned what doesn't fit
    its return type, or failed its own _check.
    """

    def __init__(self, script_id: str, why: str) -> None:
        super().__init__(f"script {script_id} failed: {why}")
        self.script_id, self.why = script_id, why


# ---------------------------------------------------------------------------
# The rules a script file must keep
# ---------------------------------------------------------------------------


def _import_problem(node: ast.Import | ast.ImportFrom) -> str:
    if isinstance(node, ast.Import):
        bad = [alias.name for alias in node.names if alias.name not in ALLOWED_IMPORTS or ALLOWED_IMPORTS[alias.name]]
        return f"`import {bad[0]}` isn't allowed" if bad else ""
    module = node.module or ""
    if node.level or module not in ALLOWED_IMPORTS:
        return f"`from {module or '.'} import ...` isn't allowed"
    names = ALLOWED_IMPORTS[module]
    bad = [alias.name for alias in node.names if names is not None and alias.name not in names]
    return f"`from {module} import {bad[0]}` isn't allowed (only {', '.join(sorted(names or []))})" if bad else ""


def _is_constant(node: ast.Assign | ast.AnnAssign) -> bool:
    """A top-level assignment a script may have: an UPPER_CASE name with a literal value, or a
    name bound to a typing Literal[...] (a parameter's choices).
    """
    targets = node.targets if isinstance(node, ast.Assign) else [node.target]
    if len(targets) != 1 or not isinstance(targets[0], ast.Name) or node.value is None:
        return False
    value = node.value
    if isinstance(value, ast.Subscript) and isinstance(value.value, ast.Name) and value.value.id == "Literal":
        return True
    try:
        ast.literal_eval(value)
    except ValueError:
        return False
    return targets[0].id.isupper()


def _top_level_problem(tree: ast.Module) -> str:
    for index, node in enumerate(tree.body):
        line = node.lineno
        match node:
            case ast.Expr(value=ast.Constant(value=str())) if index == 0:
                continue
            case ast.Import() | ast.ImportFrom():
                if problem := _import_problem(node):
                    return f"{problem} (line {line}); allowed: {', '.join(ALLOWED_IMPORTS)}"
            case ast.ClassDef():
                if not any(isinstance(base, ast.Name) and base.id == "BaseModel" for base in node.bases):
                    return f"class {node.name} must be a pydantic BaseModel (line {line}): the only classes allowed"
            case ast.FunctionDef():
                continue
            case ast.Assign() | ast.AnnAssign() if _is_constant(node):
                continue
            case _:
                return " ".join(
                    [
                        f"line {line}: the top level may hold only the docstring, imports, pydantic models,",
                        "functions and UPPER_CASE or Literal constants (nothing that runs at load time)",
                    ]
                )
    return ""


def _body_problem(tree: ast.Module) -> str:  # noqa: PLR0911  # one return per refusal reason
    for node in ast.walk(tree):
        line = getattr(node, "lineno", "?")
        match node:
            case ast.Global() | ast.Nonlocal():
                return f"`global` / `nonlocal` isn't allowed (line {line}): a script keeps no state between calls"
            case ast.AsyncFunctionDef() | ast.Await():
                return f"async code isn't allowed (line {line}): page_data is a plain call"
            case ast.Name(id=name) if name in _BANNED_NAMES or name.startswith("__"):
                return f"`{name}` isn't allowed (line {line})"
            case ast.Attribute(attr=attr) if attr.startswith("_"):
                return f"`.{attr}` isn't allowed (line {line}): no private or dunder attributes"
            case ast.Assign(targets=targets) if any(isinstance(target, ast.Attribute) for target in targets):
                return f"assigning to an attribute isn't allowed (line {line}): a script may not change other code"
            case ast.AugAssign(target=ast.Attribute()):
                return f"assigning to an attribute isn't allowed (line {line}): a script may not change other code"
    return ""


def _function_problem(tree: ast.Module, script_id: str) -> str:  # one return per broken rule
    functions = [node for node in tree.body if isinstance(node, ast.FunctionDef)]
    public = [node for node in functions if not node.name.startswith("_")]
    if len(public) != 1 or public[0].name != script_id:
        names = ", ".join(node.name for node in public) or "none"
        return " ".join(
            [
                f"a script has one public function, named as its file ({script_id}); found: {names}.",
                "Everything else starts with _; another public function is another script",
            ]
        )
    main = public[0]
    args = [*main.args.posonlyargs, *main.args.args, *main.args.kwonlyargs]
    if main.args.vararg or main.args.kwarg:
        return f"{script_id} may not take *args or **kwargs: name every parameter"
    if untyped := [arg.arg for arg in args if arg.annotation is None]:
        return f"{script_id}'s parameter {untyped[0]} has no type"
    if main.returns is None:
        return f"{script_id} has no return type"
    if not ast.get_docstring(main):
        return f"{script_id} has no docstring"
    return ""


def script_problem(code: str, script_id: str) -> str:
    """Why this code may not be saved or run as the script `script_id` ("" when it may)."""
    if not _ID.fullmatch(script_id) or script_id in _reserved():
        return f"{script_id!r} can't be a script's name: short snake_case, and not a module of ds.ai"
    try:
        tree = ast.parse(code)
    except SyntaxError as error:
        return f"not valid Python: {error.msg} (line {error.lineno})"
    if not ast.get_docstring(tree):
        return "the file must start with a docstring: its first line is the script's description in the registry"
    return _top_level_problem(tree) or _body_problem(tree) or _function_problem(tree, script_id)


def _reserved() -> set[str]:
    return {path.stem for path in Path(__file__).parent.glob("*.py")} | {"registry", "scripts"}


# ---------------------------------------------------------------------------
# The files and their registry
# ---------------------------------------------------------------------------


@dataclass(frozen=True)
class ScriptInfo:
    """One saved script, as the registry lists it."""

    id: str
    description: str
    signature: str
    """eg `google_finance_daily(ticker: str, period: Period = '1Y') -> list[DailyClose]`."""
    size: int
    """Bytes of its file."""
    problem: str = ""
    """Why it can't be run (a hand edit that broke the rules), "" when it can."""


def _path(script_id: str) -> Path:
    return SCRIPTS_DIR / f"{script_id}.py"


def _info(path: Path) -> ScriptInfo:
    code, script_id = path.read_text(encoding="utf-8"), path.stem
    if problem := script_problem(code, script_id):
        return ScriptInfo(script_id, "", "", len(code.encode()), problem)
    tree = ast.parse(code)
    main = next(node for node in tree.body if isinstance(node, ast.FunctionDef) and node.name == script_id)
    signature = f"{script_id}({ast.unparse(main.args)}) -> {ast.unparse(main.returns)}"  # type: ignore[arg-type]
    description = (ast.get_docstring(tree) or "").strip().splitlines()[0]
    return ScriptInfo(script_id, description, signature, len(code.encode()))


def registry() -> list[ScriptInfo]:
    """Every saved script, read from the files now (so an edit a moment ago is seen)."""
    if not SCRIPTS_DIR.is_dir():
        return []
    return [_info(path) for path in sorted(SCRIPTS_DIR.glob("*.py")) if not path.name.startswith("_")]


def registry_text() -> str:
    """registry.md's content, from the files: one row per script."""
    rows = [
        f"| `{info.id}` | {info.description or 'BROKEN: ' + info.problem} | `{info.signature}` | {info.size:,} |"
        for info in registry()
    ]
    return "\n".join(
        [
            "<!-- AUTO-GENERATED by ds.ai.scripts.write_registry: rebuilt from the script files, don't edit -->",
            f"<!-- {_TODO} -->",
            "",
            "# AI Scripts Registry",
            "",
            "Scripts the AI saved for itself (`ds.ai.scripts`): each `<id>.py` here has one public function,",
            "`<id>`. The AI is given these rows and reads a file when it needs it. Every save was reviewed by",
            "the user first; commit them as any code.",
            "",
            "| id | description | signature | bytes |",
            "| --- | --- | --- | --- |",
            *rows,
            "",
        ]
    )


def write_registry() -> None:
    """Rebuild registry.md from the script files."""
    SCRIPTS_DIR.mkdir(parents=True, exist_ok=True)
    (SCRIPTS_DIR / REGISTRY_NAME).write_text(registry_text(), encoding="utf-8")


def save(script_id: str, code: str) -> Path:
    """Write a script (it must keep the rules) and rebuild the registry. Only called after the
    user reviewed the code. Raises ValueError with the broken rule.
    """
    if problem := script_problem(code, script_id):
        raise ValueError(f"not saved: {problem}")
    SCRIPTS_DIR.mkdir(parents=True, exist_ok=True)
    path = _path(script_id)
    path.write_text(code.rstrip() + "\n", encoding="utf-8")
    write_registry()
    return path


def delete(script_id: str) -> bool:
    """Delete a script and rebuild the registry; False when there is none by that name."""
    path = _path(script_id)
    if not _ID.fullmatch(script_id) or not path.is_file():
        return False
    path.unlink()
    write_registry()
    return True


def dir_bytes() -> int:
    return sum(info.size for info in registry())


def over_cap() -> list[tuple[ScriptInfo, str]]:
    """When the scripts are over MAX_DIR_BYTES: each script with when it last ran ("never"
    first, then oldest), to ask the user which to delete. [] when under the cap.
    """
    if dir_bytes() <= MAX_DIR_BYTES:
        return []
    last = last_runs()
    listed = [(info, last.get(info.id, "")) for info in registry()]
    return [(info, when or "never") for info, when in sorted(listed, key=lambda pair: pair[1])]


# ---------------------------------------------------------------------------
# Running a script: fresh from its file every time
# ---------------------------------------------------------------------------


@dataclass
class ScriptRun:
    """One call of a saved script (also kept in RUNS_FILE)."""

    id: str
    kwargs: dict[str, Any]
    ok: bool = False
    why: str = ""
    """Why it failed."""
    seconds: float = 0.0
    rows: int | None = None
    fallback: str = ""
    """After a failure: 'browser' when from_url then got the value, else ''."""

    def summary(self) -> str:
        """One line for the chat."""
        args = ", ".join(f"{name}={value!r}" for name, value in self.kwargs.items())
        if self.ok:
            rows = f"{self.rows} rows, " if self.rows is not None else ""
            return f"{self.id}({args}): {rows}{self.seconds:.0f} s, no AI"
        after = "; got it with the browser instead: /script repairs it" if self.fallback else ""
        return f"{self.id}({args}) failed: {self.why}{after}"


_local = threading.local()


def runs() -> list[ScriptRun]:
    """The script calls of this thread since the last clear_runs()."""
    return list(getattr(_local, "runs", []))


def clear_runs() -> None:
    """Forget this thread's script calls (before running
    code whose calls should be reported).
    """
    _local.runs = []


def _record(made: ScriptRun) -> None:
    if not hasattr(_local, "runs"):
        _local.runs = []
    _local.runs.append(made)
    line = {"at": dt.datetime.now(dt.UTC).isoformat(timespec="seconds"), "id": made.id, "ok": made.ok}
    line |= {"kwargs": made.kwargs, "why": made.why, "seconds": round(made.seconds, 1), "rows": made.rows}
    try:
        RUNS_FILE.parent.mkdir(parents=True, exist_ok=True)
        with RUNS_FILE.open("a", encoding="utf-8") as out:
            out.write(json.dumps(line, default=str) + "\n")
    except OSError:
        pass  # history is a nicety: never fail a run over it


def _history() -> list[dict[str, Any]]:
    try:
        return [json.loads(line) for line in RUNS_FILE.read_text(encoding="utf-8").splitlines() if line.strip()]
    except (OSError, ValueError):
        return []


def last_runs() -> dict[str, str]:
    """When each script last ran, as an ISO time, by id."""
    return {line["id"]: line["at"] for line in _history()}


def past_calls(script_id: str, limit: int = 8) -> list[dict[str, Any]]:
    """The arguments of a script's latest calls: how the user tends to ask for it."""
    return [line["kwargs"] for line in _history() if line["id"] == script_id][-limit:]


def _load(code: str, script_id: str) -> dict[str, Any]:
    """The script's namespace: its code run in a fresh one (never imported, so nothing of it
    stays between calls or reaches other code by name).
    """
    if not code:
        raise ScriptFailed(script_id, "there is no such script")
    if problem := script_problem(code, script_id):
        raise ScriptFailed(script_id, f"its file breaks the script rules: {problem}")
    namespace: dict[str, Any] = {"__name__": f"ai_script_{script_id}", "__builtins__": builtins}
    # dont_inherit: without it the script would get this module's `from __future__ import
    # annotations`, and its pydantic models couldn't resolve their field types
    try:
        exec(compile(code, f"<script {script_id}>", "exec", dont_inherit=True), namespace)  # noqa: S102  # reviewed, rule-checked code
    except Exception as error:
        raise ScriptFailed(script_id, f"it doesn't load: {type(error).__name__}: {error}") from error
    return namespace


def _call(code: str, script_id: str, kwargs: dict[str, Any]) -> Any:
    """Run a script's code: its value, validated as
    its return type and passed by its _check.
    """
    namespace = _load(code, script_id)
    function = namespace[script_id]
    try:
        value = function(**kwargs)
        value = TypeAdapter(typing.get_type_hints(function)["return"]).validate_python(value)
    except ScriptFailed:
        raise
    except Exception as error:
        raise ScriptFailed(script_id, f"{type(error).__name__}: {str(error)[:300]}") from error
    check = namespace.get("_check")
    if check is not None and (why := check(value)):
        raise ScriptFailed(script_id, f"its own check says: {why}")
    return value


def run(script_id: str, **kwargs: Any) -> Any:
    """Call a saved script, read from its file now. Raises ScriptFailed with why (it raised,
    its value doesn't fit its return type, or its _check refused the value).
    """
    made = ScriptRun(script_id, kwargs)
    start = time.monotonic()
    try:
        with log_call("tool", SOURCE, name=f"script {script_id}", kwargs=kwargs) as call:
            code = _path(script_id).read_text(encoding="utf-8") if _path(script_id).is_file() else ""
            value = _call(code, script_id, kwargs)
            made.ok, made.rows = True, len(value) if isinstance(value, list) else None
            call["rows"] = made.rows
    except ScriptFailed as failed:
        made.why = failed.why
        raise
    else:
        return value
    finally:
        made.seconds = time.monotonic() - start
        _record(made)


class Scripts:
    """`scripts` in /assign code: `scripts.<id>(...)` runs that saved script. When it fails and
    the script says where its page is (`_url`), the AI browser gets the value instead
    (extract.from_url), and the failure is kept so the script can be repaired.
    """

    def __getattr__(self, script_id: str) -> Any:
        if script_id.startswith("_"):
            raise AttributeError(script_id)

        def call(*args: Any, **kwargs: Any) -> Any:
            if args:
                raise TypeError(f"scripts.{script_id} takes its arguments by name, eg {script_id}(ticker='AAPL')")
            try:
                return run(script_id, **kwargs)
            except ScriptFailed as failed:
                value = _fallback(script_id, kwargs, failed)
                runs()  # the failed run is this thread's last
                _local.runs[-1].fallback = "browser"
                return value

        return call


def _fallback(script_id: str, kwargs: dict[str, Any], failed: ScriptFailed) -> Any:
    """What the script was to return, got by the AI browser from the script's page."""
    path = _path(script_id)
    if not path.is_file():
        raise failed
    try:
        namespace = _load(path.read_text(encoding="utf-8"), script_id)
        url = namespace["_url"](**kwargs)
        shape = typing.get_type_hints(namespace[script_id])["return"]
    except Exception:  # noqa: BLE001  # no usable _url: there is nothing to fall back to
        raise failed from None
    what = f"{inspect.getdoc(namespace[script_id]) or script_id} (arguments: {kwargs})"
    try:
        value = extract.from_url(url, shape, what)
    except extract.NotOnPage as error:
        raise extract.NotOnPage(f"{failed}; then the browser didn't find it either: {error}") from error
    extract.reports()[-1].repairs = script_id
    return value


# ---------------------------------------------------------------------------
# The AI writes a script from a browser run that worked
# ---------------------------------------------------------------------------


class ScriptDraft(BaseModel):
    """A script the AI wrote, to show the user."""

    id: str = Field(description="The script's name: short snake_case, what it gets, eg google_finance_daily.")
    code: str = Field(description="The whole file. No Markdown fences.")
    example_call: str = Field(
        description=" ".join(
            [
                "A JSON object, as text, of the arguments that repeat the run this script is made from,",
                """eg {"ticker": "AAPL:NASDAQ", "period": "1Y"}. Every parameter without a default must be in it.""",
            ]
        )
    )

    def arguments(self) -> dict[str, Any]:
        """example_call as the keyword arguments to call the script with."""
        value = json.loads(self.example_call)
        if not isinstance(value, dict):
            raise TypeError("example_call must be a JSON object")
        return value


@dataclass
class _Drafting:
    """One draft, for its check."""

    expected: list[Any] | None
    """The rows the AI run got: a code-only run of the draft must give them again."""
    verified: str = ""
    """What the code-only run of the accepted draft gave, in words."""
    tried: list[str] = field(default_factory=list)
    last_code: str = ""
    """The latest draft's code, kept so a draft that never passed can still be shown."""


_EXAMPLE = '''
"""Daily closing prices and volume for a ticker from Google Finance."""

from datetime import date
from typing import Literal

from pydantic import BaseModel

from ds.ai.extract import page_data

Period = Literal["1M", "6M", "1Y", "5Y"]
MIN_ROWS = 15


class DailyClose(BaseModel, frozen=True):
    date: date
    close: float  # closing price in USD
    volume: int | None = None  # shares traded


def google_finance_daily(ticker: str, period: Period = "1Y") -> list[DailyClose]:
    """Daily closes for `ticker` (eg "AAPL:NASDAQ") over `period`, oldest first."""
    body = page_data(_url(ticker, period), clicks=[period], response="rpcids=c2u4wc")
    return _parse(body)


def _url(ticker: str, period: Period = "1Y") -> str:
    return f"https://www.google.com/finance/quote/{ticker}"


def _parse(body: str) -> list[DailyClose]:
    ...


def _check(rows: list[DailyClose]) -> str:
    return "" if len(rows) >= MIN_ROWS else f"only {len(rows)} rows"
'''

_DRAFT_RULES = clean_f_str("""
    You turn a browser run that worked into a saved script: a small Python file that gets the same data
    later with no AI. You are given what the run did (the page, the labels clicked, the part of the data
    response's URL, the parser that worked) and the model class the data was put in.

    The file's rules (it is refused otherwise):
    - It starts with a docstring whose first line says what the script gets (shown in a registry).
    - One public function, named exactly as the script's id, every parameter and the return typed, with a
      docstring. It calls page_data(url, clicks=[...], response="...") and parses the body.
    - Everything else is private (starts with _). Always include `_url(...)`, taking the same parameters as
      the public function and returning the page's URL (used when the script stops working), and `_check(rows)
      -> str` returning "" or why the result looks wrong (eg too few rows).
    - The model class(es) the function returns are defined in the file, as given to you.
    - Imports only from: json, re, math, datetime, typing, pydantic, and `from ds.ai.extract import page_data`.
      No `from __future__ import annotations`.
    - The top level holds only the docstring, imports, model classes, functions and UPPER_CASE or Literal
      constants. No global state, no open / eval / exec / getattr, no private attributes of other objects.
    - Turn what varies between asks into typed parameters with defaults (a ticker, a range: a Literal of the
      labels the page offers when you know them), not into new scripts. Keep what the run used as the default.
    - Keep the parser as it worked; put it in `_parse`.

    When an existing script for the same site and return shape is given, change that script instead of
    writing a new one (answer with its id): repair it, or add the parameter the new ask needed, keeping
    its earlier calls working. Its past calls show how the user tends to ask.

    example_call must be the arguments that repeat the run you were given: your script is run with them,
    with no AI, and must give the same rows, or it comes back to you.

    The shape of a script file:
    """)
_DRAFT_RULES = "\n".join([_DRAFT_RULES, _EXAMPLE])

draft_agent = Agent(
    ai_model(),
    # on its Logfire spans: the Spend tab lists it apart from the chat
    name="script-writer",
    # resolved at run time, so importing ds.ai works without a key (as ds.ai.agent)
    defer_model_check=True,
    instructions=_DRAFT_RULES,
    output_type=ScriptDraft,
    deps_type=_Drafting,
    retries=DRAFT_FIXES,
)


def _same(rows: Any, expected: list[Any]) -> tuple[int, int]:
    """(expected rows the code-only run also gave, expected rows), compared as plain data: the
    script's model class is its own, not the session's.
    """

    def plain(value: Any) -> str:
        return json.dumps(value.model_dump(mode="json") if isinstance(value, BaseModel) else value, sort_keys=True)

    got = {plain(row) for row in rows} if isinstance(rows, list) else set()
    return sum(1 for row in expected if plain(row) in got), len(expected)


@draft_agent.output_validator
async def _check_draft(ctx: RunContext[_Drafting], output: ScriptDraft) -> ScriptDraft:
    """A draft must keep the rules and, run with no AI, give the rows the AI run gave: else it
    goes back to the model with why.
    """
    drafting = ctx.deps
    drafting.last_code = output.code
    if problem := script_problem(output.code, output.id):
        drafting.tried.append(f"refused: {problem}")
        raise ModelRetry(f"The script breaks a rule: {problem}. Send the corrected file.")
    try:
        kwargs = output.arguments()
    except (ValueError, TypeError) as error:
        raise ModelRetry(f"example_call isn't a JSON object of arguments: {error}") from error
    try:
        # page_data starts its own event loop: run the script off this one
        rows = await asyncio.to_thread(_call, output.code, output.id, kwargs)
    except ScriptFailed as failed:
        drafting.tried.append(f"code-only run failed: {failed.why}")
        raise ModelRetry(f"Run with {kwargs} and no AI, the script failed: {failed.why}") from failed
    count = len(rows) if isinstance(rows, list) else 1
    if drafting.expected:
        same, total = _same(rows, drafting.expected)
        if same < VERIFY_SHARE * total:
            drafting.tried.append(f"code-only run gave {same} of the AI run's {total} rows")
            fix = "Check the clicks, the response part and the parser."
            got = f"the script gave {count} rows, only {same} of the {total} the browser run got"
            raise ModelRetry(f"Run with {kwargs}, {got}. {fix}")
        drafting.verified = f"a code-only run gave {same} of the AI run's {total} rows"
    else:
        drafting.verified = f"a code-only run gave {count} rows (nothing to compare them with)"
    return output


@dataclass
class Drafted:
    """What draft() gave back: the script to review, or why there is none."""

    id: str = ""
    code: str = ""
    verified: str = ""
    replaces: bool = False
    """Whether a script by this id exists already (a repair, or a widened script)."""
    error: str = ""
    tried: list[str] = field(default_factory=list)
    cost: float = 0.0


def _existing_for(url: str) -> list[ScriptInfo]:
    """Saved scripts that read the same site (their code names its host)."""
    host = (urlparse(url).hostname or "").removeprefix("www.")
    return [info for info in registry() if host and host in _path(info.id).read_text(encoding="utf-8")]


async def draft(report: extract.FromUrlReport, shape_code: str, expected: list[Any] | None, name: str = "") -> Drafted:
    """The AI writes (or repairs, or widens) a script from a browser run that worked.

    report: the from_url run (savable). shape_code: the code that defined the model class(es)
    and made the call (the /assign proposal). expected: the rows that run got. name: the user's
    name for a new script, "" = the AI picks.
    """
    parts = [
        f"The run: from_url({report.url!r}, ..., {report.what!r})",
        f"Labels clicked, in order: {report.clicks}",
        f"The data response's URL contains: {report.response_contains!r}",
        f"The parser that worked (its `parse` becomes `_parse`):\n{report.parse_code}",
        f"The code that defined the model class(es) and asked for the data:\n{shape_code}",
    ]
    if name:
        parts.append(f"The user named the script: {name}")
    for info in _existing_for(report.url):
        role = "FAILED and must be repaired (keep its id)" if info.id == report.repairs else "reads the same site"
        parts.append(f"Existing script `{info.id}` ({role}); its past calls: {past_calls(info.id)}; its file:")
        parts.append(_path(info.id).read_text(encoding="utf-8"))
    drafting = _Drafting(expected=expected)
    made = Drafted()
    with log_call("agent", SOURCE, name="script draft", url=report.url) as call:
        try:
            result = await draft_agent.run("\n\n".join(parts), deps=drafting)
        except Exception as error:  # noqa: BLE001  # shown in the chat; the tries say what went wrong
            made.error = f"no script: {type(error).__name__}: {str(error)[:200]}"
            made.code = drafting.last_code
            call["error"] = made.error
        else:
            made.id, made.code, made.verified = result.output.id, result.output.code.strip(), drafting.verified
            made.replaces = _path(made.id).is_file()
            made.cost = call["cost"] = float(result.usage.cost or 0)
        made.tried = call["tried"] = drafting.tried
    return made
